\set ON_ERROR_STOP on

drop schema if exists public cascade;
drop schema if exists auth cascade;
create schema public;
create schema auth;
grant usage on schema public, auth to public;

do $roles$
begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then
    create role anon nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then
    create role authenticated nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'service_role') then
    create role service_role nologin bypassrls;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'mila_acesso_restrito') then
    create role mila_acesso_restrito nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'sol_acesso_restrito') then
    create role sol_acesso_restrito nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'fabio_agent') then
    create role fabio_agent nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'lia_acesso_restrito') then
    create role lia_acesso_restrito nologin;
  end if;
end;
$roles$;

create or replace function auth.uid()
returns uuid
language sql
stable
as $function$
  select nullif(
    current_setting('request.jwt.claim.sub', true),
    ''
  )::uuid;
$function$;

create table public.unidades (
  id uuid primary key,
  nome text not null
);

create table public.usuarios (
  id integer primary key,
  auth_user_id uuid unique,
  nome text not null,
  perfil text not null,
  unidade_id uuid references public.unidades(id),
  ativo boolean not null default true
);

create table public.whatsapp_caixas (
  id integer generated by default as identity primary key,
  nome varchar not null,
  numero varchar,
  uazapi_url varchar not null,
  uazapi_token varchar not null,
  unidade_id uuid references public.unidades(id),
  ativo boolean default true,
  webhook_url text,
  created_at timestamptz default now(),
  updated_at timestamptz default now(),
  funcao text not null default 'agente'
    check (funcao in ('agente', 'sistema', 'ambos', 'administrativo')),
  provedor text not null default 'uazapi',
  waha_url text,
  waha_session text,
  waha_api_key text,
  departamento text not null default 'administrativo'
    check (departamento in ('administrativo', 'sucesso_aluno'))
);

alter table public.whatsapp_caixas enable row level security;
create policy whatsapp_caixas_select
  on public.whatsapp_caixas for select to authenticated using (true);
create policy whatsapp_caixas_insert
  on public.whatsapp_caixas for insert to authenticated with check (true);
create policy whatsapp_caixas_update
  on public.whatsapp_caixas for update to authenticated
  using (true) with check (true);
create policy whatsapp_caixas_delete
  on public.whatsapp_caixas for delete to authenticated using (true);

grant all on table public.whatsapp_caixas
  to anon, authenticated, service_role, mila_acesso_restrito,
     sol_acesso_restrito, fabio_agent, lia_acesso_restrito;
grant all on sequence public.whatsapp_caixas_id_seq
  to anon, authenticated, service_role, mila_acesso_restrito,
     sol_acesso_restrito, fabio_agent, lia_acesso_restrito;

